// src/pages/Home.jsx
import { useState, useEffect, useRef } from "react";
import { useNavigate } from "react-router-dom";
import { useUI } from "../context/UIContext";
import Input from "../components/common/Input";
import Button from "../components/common/Button";
import styles from "../Home.module.css";

const Home = () => {
  const navigate = useNavigate();
  const { setHeroData, setAllAnswers } = useUI();
  const videoRef = useRef(null);

  const [isPlaying, setIsPlaying] = useState(false);
  const [formData, setFormData] = useState({
    userName: "",
    birthday: "",
  });

  useEffect(() => {
    setHeroData({
      imageUrl: "/assets/helperinside.png",
      title: "乳房手術方式輔助決策小幫手",
      description: "歡迎使用！請填寫基本資料，再按下開始。",
    });
  }, [setHeroData]);

  // 切換播放/暫停
  const handleToggleVideo = () => {
    if (!videoRef.current) return;
    if (isPlaying) {
      videoRef.current.pause();
      setIsPlaying(false);
    } else {
      videoRef.current
        .play()
        .then(() => setIsPlaying(true))
        .catch((err) => console.log("影片播放受阻：", err));
    }
  };

  const handleStart = () => {
    if (!formData.userName || !formData.birthday) {
      alert("請填寫完整資料後再開始");
      return;
    }

    if (videoRef.current) {
      videoRef.current.pause();
    }

    setAllAnswers((prev) => ({
      ...prev,
      userName: formData.userName,
      birthday: formData.birthday,
    }));

    navigate("/selection");
  };

  const handleInputChange = (event) => {
    const { name, value } = event.target;
    setFormData((prev) => ({ ...prev, [name]: value }));
  };

  return (
    <div className={styles.homeContainer}>
      {/* 左側/上方：大畫面沉浸式視訊區 */}
      <div className={styles.videoSection}>
        <div className={styles.videoWrapper} onClick={handleToggleVideo}>
          <video
            ref={videoRef}
            src="/assets/eve_sdm_talk.mp4"
            playsInline
            className={styles.mainVideo}
            onEnded={() => setIsPlaying(false)}
          />

          {/* 懸浮播放按鈕（播放時隱藏，暫停時浮現） */}
          {!isPlaying && (
            <div className={styles.playOverlay}>
              <div className={styles.playIcon}>▶</div>
              <p className={styles.playText} style={{ margin: "8px 0 0 0" }}>
                點擊聆聽小幫手導覽
              </p>
            </div>
          )}

          {/* 播放時的頂部動態狀態條 */}
          {isPlaying && (
            <div className={styles.liveBadge}>
              <span className={styles.liveDot}></span> 引導語音播放中
            </div>
          )}
        </div>
      </div>

      {/* 右側/下方：基本資料輸入表單區 */}
      <div className={styles.formSection}>
        <div className={styles.formCard}>
          <h2 className={styles.formTitle}>請填寫基本資料</h2>
          <p className={styles.formSubtitle}>
            完成後點擊下方按鈕即可開始決策流程
          </p>

          <div className={styles.inputWrapper}>
            <Input
              label="請輸入您的姓名"
              name="userName"
              placeholder="請輸入您的姓名"
              value={formData.userName}
              onChange={handleInputChange}
            />

            <Input
              label="請輸入您的出生年月日"
              type="date"
              name="birthday"
              value={formData.birthday}
              onChange={handleInputChange}
            />
          </div>

          <div className={styles.buttonWrapper}>
            <Button onClick={handleStart} fullWidth>
              開始選擇手術主題 ➔
            </Button>
          </div>
        </div>
      </div>
    </div>
  );
};

export default Home;
